style.css:
@-moz-document domain("open.spotify.com") {
body {
    background: url("https://i.imgur.com/FMuDziZ.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    font-family: 'Brush Script MT', cursive !important;
    font-weight: bold !important;
    color: #222 !important;
  }

  .Root__main-view, .main-view-container__scroll-node, .main-navBar-navBar {
    background-color: rgba(255, 240, 250, 0.5) !important;
    backdrop-filter: blur(12px);
    border-radius: 10px;
  }

  .Type__base, .Type__base__main, .Type__title, .Type__text, .Type__root {
    font-family: 'Brush Script MT', cursive !important;
    font-weight: bold !important;
    color: #333 !important;
  }

  a {
    color: #cc3399 !important;
  }

  a:hover {
    color: #ff66cc !important;
  }

  button, .ButtonInner-sc-14ud5tc-0 {
    background-color: rgba(255, 255, 255, 0.4) !important;
    color: #d63384 !important;
    border-radius: 12px !important;
    border: none !important;
    font-weight: bold !important;
  }
}
